-- Phase 1: core product fields. ADDITIVE ONLY - adds columns, indexes and CHECK constraints to `product`.
-- It never drops, truncates or deletes anything. All new columns are NULL-able or have defaults, so existing rows stay valid.
-- Applied once by scripts/migrate-product.js (skipped automatically when the `publish_status` column already exists).
--
-- Pricing model:  mrp (printed price) >= selling_price (= the regular price) >= sale_price (optional, optional date window).
--                 discount_amount / discount_percent stay generated by MySQL from mrp and selling_price.
-- Status:         `publish_status` is draft | published | inactive. The old `status` flag is kept and always equals
--                 (publish_status = 'published'), so existing queries and the UI keep working.
ALTER TABLE product
  ADD COLUMN sku                 VARCHAR(64)  CHARACTER SET ascii COLLATE ascii_general_ci NULL AFTER product_name,
  ADD COLUMN slug                VARCHAR(200) CHARACTER SET ascii COLLATE ascii_general_ci NULL AFTER sku,
  ADD COLUMN product_type        ENUM('simple','variable') NOT NULL DEFAULT 'simple' AFTER slug,
  ADD COLUMN is_virtual          TINYINT(1) NOT NULL DEFAULT 0 AFTER product_type,
  ADD COLUMN is_downloadable     TINYINT(1) NOT NULL DEFAULT 0 AFTER is_virtual,
  ADD COLUMN short_description   TEXT NULL AFTER description,
  ADD COLUMN sale_price          DECIMAL(10,2) NULL AFTER selling_price,
  ADD COLUMN sale_start          TIMESTAMP NULL DEFAULT NULL AFTER sale_price,
  ADD COLUMN sale_end            TIMESTAMP NULL DEFAULT NULL AFTER sale_start,
  ADD COLUMN tax_status          ENUM('taxable','shipping','none') NOT NULL DEFAULT 'taxable' AFTER gst_percent,
  ADD COLUMN manage_stock        TINYINT(1) NOT NULL DEFAULT 1 AFTER stock_quantity,
  ADD COLUMN backorders          ENUM('no','notify','yes') NOT NULL DEFAULT 'no' AFTER manage_stock,
  ADD COLUMN low_stock_threshold INT UNSIGNED NULL AFTER backorders,
  ADD COLUMN stock_status        ENUM('instock','outofstock','onbackorder') NOT NULL DEFAULT 'instock' AFTER low_stock_threshold,
  ADD COLUMN weight              DECIMAL(10,3) NULL,
  ADD COLUMN length              DECIMAL(10,2) NULL,
  ADD COLUMN width               DECIMAL(10,2) NULL,
  ADD COLUMN height              DECIMAL(10,2) NULL,
  ADD COLUMN shipping_class      VARCHAR(100) NULL,
  ADD COLUMN requires_shipping   TINYINT(1) NOT NULL DEFAULT 1,
  ADD COLUMN seo_title           VARCHAR(255) NULL,
  ADD COLUMN meta_description    VARCHAR(500) NULL,
  ADD COLUMN focus_keyword       VARCHAR(150) NULL,
  ADD COLUMN additional_keywords JSON NULL COMMENT 'list of strings',
  ADD COLUMN canonical_url       VARCHAR(500) NULL,
  ADD COLUMN publish_status      ENUM('draft','published','inactive') NOT NULL DEFAULT 'published' AFTER status,
  ADD UNIQUE KEY uk_product_sku (sku),
  ADD UNIQUE KEY uk_product_slug (slug),
  ADD KEY idx_product_type (product_type),
  ADD KEY idx_product_publish_status (publish_status),
  ADD KEY idx_product_stock_status (stock_status),
  ADD CONSTRAINT chk_product_sale_price CHECK (sale_price IS NULL OR (sale_price > 0 AND sale_price <= selling_price)),
  ADD CONSTRAINT chk_product_sale_dates CHECK (sale_start IS NULL OR sale_end IS NULL OR sale_end > sale_start),
  ADD CONSTRAINT chk_product_dimensions CHECK ((weight IS NULL OR weight >= 0) AND (length IS NULL OR length >= 0) AND (width IS NULL OR width >= 0) AND (height IS NULL OR height >= 0));
-- @@
-- Existing rows: status 1 -> published, status 0 -> inactive. (Only touches the new column; `status` is not changed.)
UPDATE product SET publish_status = IF(status = 1, 'published', 'inactive');
